functionImplementations.selectedEntity:
// Unable to retrieve the property in the normal way because the API only applies to generic dimensions. Entity is organisational.
// Returns:
//  Entity ID in position 1 i.e. [0] e.g. [PPP_Entity].[H1].&[ND10]
//  Entity ID (simple) in position 2 i.e. [1] e.g. ND10
//  Entity classification in position 2 i.e. [2] e.g. "REFINERIE"

var resultList = ArrayUtils.create(Type.string);
var tableRS = Table_HelperEntity.getDataSource().getResultSet();

resultList[0] = tableRS[0]["PPP_Entity"].id;
resultList[1] = BusRules.simpleMemberID(resultList[0]);
resultList[2] = tableRS[0]["PPP_Entity"].properties["PPP_Entity.Classification"];

//console.log(resultList);
return (resultList);

functionImplementations.EntityProductList:
Application.showBusyIndicator("Fetching the entity product list");

var productList = ArrayUtils.create(Type.string);

// Return an empty filter if no Entity was supplied
if (Entity === "") {
	return false;
}

// Get all ProductServ members from the planning model
var products = PlanningModel_BusPremise.getMembers("ProductServ", {
	limit: 500
});

//console.log("All products in the model:");
//console.log(products);

// Loop through all ProductServ members
for (var i = 0; i < products.length; i++) {

	var product = products[i];
//	console.log(products[i].id);

	// Ignore the # product
	if (product === undefined || product.id === "#" || product.id === "") {
		continue;
	}	

	// Get the Entities property
	var entityProperty = product.properties["Entities"];
//	console.log("This product:");
//	console.log(products[i]);
//	console.log("Has these entities");
//	console.log(entityProperty);
//	console.log("Looking for:");
//	console.log(Entity);

	// Ignore products with no Entities property value
	if (entityProperty === undefined || entityProperty === "") {
		continue;
	}

	// Split the comma-separated Entity list
	var entities = entityProperty.split(",");
//	console.log(entities);

	// Check each Entity ID
	for (var j = 0; j < entities.length; j++) {

		// Remove leading/trailing spaces
		var currentEntity = entities[j].trim();

		// Exact Entity ID match
		if (currentEntity === Entity) {

			productList.push("[ProductServ].[H1].[" + product.id + "]");

			// No need to check the remaining Entity values
			break;
		}
	}
}

console.log(productList);
Table_1.getDataSource().setDimensionFilter("ProductServ", productList);
Table_6.getDataSource().setDimensionFilter("ProductServ", productList);

Application.hideBusyIndicator();

return true;

functionImplementations.EntityChange:
var thisEntity = BusRules.selectedEntity()[1];

if (thisEntity !== CurrentEntity ) {
	CurrentEntity = thisEntity;
	BusRules.EntityProductList(thisEntity);
}

